function heartQuizStored(){S.me=S.me||{};const d=S.me.heartQuizDraft;return d&&d.cid&&getC(d.cid)&&Array.isArray(d.questions)?d:null;}
function heartQuizClone(v){try{return JSON.parse(JSON.stringify(v));}catch(_){return null;}}
function heartQuizSave(){if(!_hq)return false;const d=heartQuizClone(_hq);if(!d)return false;delete d.scarePulse;delete d.lovePulse;delete d.busy;d.updatedAt=Date.now();S.me=S.me||{};S.me.heartQuizDraft=d;save();return true;}
function heartQuizDrop(){S.me=S.me||{};delete S.me.heartQuizDraft;save();}
function heartQuizModeName(mode){return mode==='dark'?'黑卷':'白卷';}
function heartQuizLevelName(mode,level){const row=HEART_QUIZ_LEVELS[mode==='dark'?'dark':'white'][Math.max(0,Math.min(2,(+level||1)-1))];return row?row[0]:'进阶';}
function heartQuizHash(text){let h=2166136261;for(const ch of String(text||'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function heartQuizFallback(mode,level,cid,stamp){const bank=HEART_QUIZ_BANK[mode==='dark'?'dark':'white'],traits=mode==='dark'?['possess','obsess','defy']:['bond','balance','space'],base=Math.max(1,Math.min(5,(+level||2)*2-1));return bank.slice(0,HEART_QUIZ_TOTAL).map((row,i)=>({id:'hq'+(i+1),q:row[0],options:row[1].slice(0,3),traits:traits.slice(),roleChoice:heartQuizHash(cid+'|'+level+'|'+stamp+'|'+i)%3,intensity:Math.max(1,Math.min(5,base+(i>19?1:i<5?-1:0))),reactions:[]}));}
function heartQuizQuestionForUser(q){const text=String(q||'').trim(),last=(text.split(/[，,；;]/).pop()||'').trim();return text.includes('你')&&last.includes('你')&&!/(?:我会|我该|我应该|我想|我愿意|我希望|我最|我觉得|我认为)[^？?]*[？?]$/.test(last);}
function heartQuizTextRows(raw){let text=String(raw||'').replace(/```(?:json|text)?/gi,'').replace(/```/g,'').replace(/\r/g,'').replace(/[ＡＢＣ]/g,ch=>({Ａ:'A',Ｂ:'B',Ｃ:'C'})[ch]).trim();if(!text)return[];text=text.replace(/[；;]\s*(?=(?:题目|问题|Q\s*\d*|选项\s*[ABC]|[ABC]|期待|答案|强度|难度|刺激度|(?:角色\s*)?(?:反应|回应|回复))\s*[：:])/gi,'\n');const starts=[];for(const re of [/^\s*(?:#{1,4}\s*)?(?:[-*]\s*)?(?:(?:第\s*)?\d+\s*题?\s*[.、:：)）-]?\s*)?(?:题目|问题|Q)\s*\d*\s*[：:、.．)）-]\s*/gmi,/^\s*(?:第\s*)?\d+\s*题\s*[.、:：)）-]?\s*[^\n]{4,}[？?]\s*$/gm]){let m;while((m=re.exec(text)))starts.push(m.index);}const unique=[...new Set(starts)].sort((a,b)=>a-b);if(!unique.length)unique.push(0);const labelValue=(block,label)=>{const m=block.match(new RegExp('^\\s*(?:#{1,4}\\s*)?(?:[-*]\\s*)?(?:\\d+\\s*[.、)）]\\s*)?\\*{0,2}'+label+'\\*{0,2}\\s*[：:、.．)）-]+\\s*(.+?)\\s*$','mi'));return m?m[1].replace(/\*+$/,'').trim():'';},rows=[];for(let i=0;i<unique.length;i++){const block=text.slice(unique[i],unique[i+1]||text.length).trim();if(!block)continue;let q=labelValue(block,'(?:(?:第\\s*)?\\d+\\s*题\\s*)?(?:题目|问题|Q)\\s*\\d*');if(!q){const first=block.match(/^\s*(?:第\s*)?\d+\s*题\s*[.、:：)）-]?\s*([^\n]+[？?])/m);q=first&&first[1]||'';}const opts=['A','B','C'].map(letter=>labelValue(block,'(?:选项\\s*)?'+letter+'(?:\\s*选项)?'));let reactions=['A','B','C'].map(letter=>labelValue(block,'(?:(?:角色\\s*)?(?:反应|回应|回复)\\s*'+letter+'|(?:角色\\s*)?(?:对\\s*)?'+letter+'(?:\\s*选项)?(?:\\s*的)?\\s*(?:反应|回应|回复))'));if(reactions.filter(Boolean).length<3){const section=block.match(/^\s*(?:角色\s*)?(?:反应|回应|回复)(?:列表)?\s*[：:]\s*\n([\s\S]*)$/mi);if(section){const grouped=['A','B','C'].map(letter=>labelValue(section[1],letter));if(grouped.filter(Boolean).length>reactions.filter(Boolean).length)reactions=grouped;}}const expected=labelValue(block,'(?:(?:角色|TA)\\s*)?(?:期待(?:答案)?|正确答案|答案|选择|roleChoice)'),intensity=labelValue(block,'(?:强度(?:等级)?|难度|刺激度|程度|intensity)');if(q&&opts.some(Boolean)||reactions.some(Boolean))rows.push({q,options:opts,roleChoice:expected,intensity,reactions});}return rows;}
function heartQuizLooseRows(raw){let value=null;try{value=parseArr(raw);}catch(_){}if(Array.isArray(value))return value;if(value&&typeof value==='object'){for(const key of ['questions','items','data','题目'])if(Array.isArray(value[key]))return value[key];}let text=String(raw||''),fence=text.match(/```(?:json)?\s*([\s\S]*?)(?:```|$)/i);if(fence)text=fence[1];const rows=[];let start=-1,depth=0,quote='',escaped=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quote){if(escaped)escaped=false;else if(ch==='\\')escaped=true;else if(ch===quote)quote='';continue;}if(ch==='"'||ch==="'"){quote=ch;continue;}if(ch==='{'){if(depth===0)start=i;depth++;continue;}if(ch==='}'&&depth){depth--;if(depth===0&&start>=0){const part=text.slice(start,i+1).replace(/,(\s*[}\]])/g,'$1');try{const row=JSON.parse(part);if(row&&typeof row==='object')rows.push(row);}catch(_){}start=-1;}}}return rows.length?rows:heartQuizTextRows(raw);}
function heartQuizList(v){if(Array.isArray(v))return v;if(v&&typeof v==='object')return Object.keys(v).sort().map(k=>v[k]);return[];}
function heartQuizPlain(v,n){return String(v&&typeof v==='object'?(v.text||v.content||v.label||v.value||''):(v==null?'':v)).replace(/\s+/g,' ').trim().slice(0,n);}
function heartQuizOption(v){let text=heartQuizPlain(v,90).replace(/^(?:选项\s*)?[A-CＡ-Ｃ1-3一二三][.、:：)）\s-]*/i,'').trim();text=text.replace(/^你会/,'我会').replace(/^你想/,'我想').replace(/^你要/,'我要').replace(/^你选择/,'我选择');if(text&&!/^我/.test(text))text='我会'+text.replace(/^[，,。\s]+/,'');return text.slice(0,90);}
function heartQuizReaction(v){return heartQuizPlain(v,90).replace(/^(?:反应\s*)?[A-CＡ-Ｃ1-3一二三][.、:：)）\s-]*/i,'').replace(/[“”"]/g,'').trim().slice(0,72);}
function heartQuizQuestion(v){let text=heartQuizPlain(v,140).replace(/^(?:问题|题目|Q)\s*\d*\s*[.、:：)）\s-]*/i,'').trim();if(text&&!/[？?]$/.test(text))text+='？';if(!heartQuizQuestionForUser(text))text=text.replace(/([，,；;])\s*我(?:会|该|应该|想|愿意|希望|最|觉得|认为)[^？?]*[？?]?$/,'$1你会怎么做？');return text.slice(0,120);}
function heartQuizRoleChoice(x,opts,cid,level,stamp,index){let raw=x&&x.roleChoice;if(raw==null&&x){if(x.expectedIndex!=null)raw=x.expectedIndex;else if(x.expected!=null)raw=x.expected;else if(x.choice!=null)raw=x.choice;else raw=x['期待'];}if(typeof raw==='string'){const letter=raw.trim().match(/^[A-CＡ-Ｃ]$/i);if(letter)raw='ABC'.indexOf(letter[0].toUpperCase().replace('Ａ','A').replace('Ｂ','B').replace('Ｃ','C'));else{const matched=opts.findIndex(o=>o===heartQuizOption(raw));if(matched>=0)raw=matched;}}let rc=Math.floor(Number(raw));if(!(rc>=0&&rc<3))rc=heartQuizHash(cid+'|'+level+'|'+stamp+'|'+index)%3;return rc;}
function heartQuizIntensity(v){if(typeof v==='string'){const labels={轻:1,低:1,中:3,高:4,重:4,深:5,失控:5,极端:5};for(const key in labels)if(v.includes(key))return labels[key];}return Math.max(1,Math.min(5,Math.round(Number(v)||3)));}
function heartQuizDiagAdd(diag,key){if(!diag)return;diag[key]=(diag[key]||0)+1;}
function heartQuizDiagText(diag){if(!diag)return'';const parts=[];if(diag.badQuestion)parts.push('问题视角'+diag.badQuestion);if(diag.missingOptions)parts.push('选项缺失'+diag.missingOptions);if(diag.missingReactions)parts.push('反应缺失'+diag.missingReactions);if(diag.duplicate)parts.push('重复'+diag.duplicate);if(diag.requestErrors)parts.push('请求失败'+diag.requestErrors);if(diag.noAccepted)parts.push('空批'+diag.noAccepted);return parts.slice(0,4).join('、');}
function heartQuizNormalizeRows(raw,mode,cid,level,stamp,existing,diag){const seen=new Set((existing||[]).map(x=>String(x.q||'').replace(/[，。？！\s]/g,''))),traits=mode==='dark'?['possess','obsess','defy']:['bond','balance','space'],out=[],source=heartQuizLooseRows(raw);if(diag)diag.parsed=(diag.parsed||0)+source.length;for(const x of source){const q=heartQuizQuestion(x&&(x.q||x.question||x.prompt||x['问题']||x['题目'])),optionSource=x&&(x.options||x.answers||x.choices||x['选项']||(x.A||x.B||x.C?[x.A,x.B,x.C]:null)),opts=heartQuizList(optionSource).map(heartQuizOption).filter(Boolean).slice(0,3);let reactionSource=x&&(x.reactions||x.responses||x.replies||x['反应']);if(!reactionSource&&x)reactionSource=[x.reactionA||x.reaction_a||x.responseA||x['反应A'],x.reactionB||x.reaction_b||x.responseB||x['反应B'],x.reactionC||x.reaction_c||x.responseC||x['反应C']];const reactions=heartQuizList(reactionSource).map(heartQuizReaction).filter(Boolean).slice(0,3),key=q.replace(/[，。？！\s]/g,'');if(q.length<5||!heartQuizQuestionForUser(q)){heartQuizDiagAdd(diag,'badQuestion');continue;}if(opts.length<3){heartQuizDiagAdd(diag,'missingOptions');continue;}if(reactions.length<3){heartQuizDiagAdd(diag,'missingReactions');continue;}if(seen.has(key)){heartQuizDiagAdd(diag,'duplicate');continue;}seen.add(key);const offset=(existing||[]).length+out.length,rc=heartQuizRoleChoice(x,opts,cid,level,stamp,offset),intensity=heartQuizIntensity(x&&(x.intensity||x.difficulty||x.level||x['强度']||x['难度']));out.push({id:'hq'+(offset+1),q,options:opts,traits:traits.slice(),roleChoice:rc,intensity,reactions});heartQuizDiagAdd(diag,'accepted');if(offset+1===HEART_QUIZ_TOTAL)break;}return out;}
function heartQuizNormalize(raw,mode,cid,level,stamp){const out=heartQuizNormalizeRows(raw,mode,cid,level,stamp,[]);return out.length===HEART_QUIZ_TOTAL?out:[];}
function heartQuizQuestionPrompt(c,g,count,batch,avoid){const dark=g.mode==='dark';return buildSystem(c,{worldbookScope:'games'})+'\n\n# 心动审判出题任务（第'+batch+'小批）\n你正在向'+S.me.name+'发起一场纯虚构的情侣审判游戏。本次只写'+count+'道题，不要写整份30题。完全按你自己的人设、记忆、关系、妒意和占有欲决定题目与1到5级强度。卷面：'+heartQuizModeName(g.mode)+'。\n'+(dark?'黑卷要暗黑、惊辣、偏执、病态、有占有和失控感，由你按人设决定这一批有多重。':'白卷围绕日常默契、信任、吃醋、未来、亲密偏好与个人空间，由你按人设决定深浅。')+'\n问题必须是你直接问'+S.me.name+'会怎么做或怎么选择，问题里的“你”指'+S.me.name+'；不能问你自己会怎样。三个选项都是'+S.me.name+'的回答，并以“我”开头。\n每个选项都要有一句你看到ta选择后立刻会说的反应，三句顺序对应三个选项，必须结合具体答案和你的人设。\n不要写JSON。逐题严格使用下面九行纯文字格式；每个标签单独一行，不能省略，题与题之间写---：\n题目：如果有人故意靠近你，你会怎么做？\nA：我会马上拒绝\nB：我会先看你的反应\nC：我会故意让你吃醋\n期待：A\n强度：4\n反应A：这样才算乖\n反应B：你还敢先看我？\n反应C：很好，这笔账我会亲自讨\n共写'+count+'题，期待只写A、B或C，强度只写1到5；不要标题、解释、Markdown或代码框。'+(avoid?'\n不要重复这些已经采用的题目：'+avoid:'');}
async function heartQuizGenerate(c,g){const isPreview=g.source==='preview'&&typeof NORTH_PREVIEW_PARAMS==='string'&&NORTH_PREVIEW_PARAMS.includes('heartquiz'),stamp=isPreview?12345:Date.now();if(g.source!=='role')return heartQuizFallback(g.mode,g.level,g.cid,stamp);const out=[],diag={requests:0,parsed:0,accepted:0},requestBatch=async(count,batch,single)=>{diag.requests++;const avoid=out.slice(-30).map(x=>x.q).join('；'),prompt=heartQuizQuestionPrompt(c,g,count,batch,avoid);let raw='';try{raw=await chatAPI([{role:'system',content:prompt},{role:'user',content:single?'现在只补1题，完整写完九行；不要解释，也不要重复旧题。':'只生成这一小批'+count+'题。按九行文字格式写，写完每题的反应C再进入下一题。'}],{aux:true,max:single?1200:2400,temp:single?.86:.92,timeout:90000,complete:true,roleInterceptAudit:null,roleInterceptStage:single?'心动审判逐题补齐':'心动审判分批出题'});}catch(e){heartQuizDiagAdd(diag,'requestErrors');diag.lastError=String(e&&e.message||'请求失败').slice(0,80);return 0;}const rows=heartQuizNormalizeRows(raw,g.mode,g.cid,g.level,stamp,out,diag);if(!rows.length){heartQuizDiagAdd(diag,'noAccepted');return 0;}out.push(...rows);if(_hq===g){g.loadingDone=out.length;render();}return rows.length;};let misses=0,batch=0;while(out.length<HEART_QUIZ_TOTAL&&batch<12){batch++;const added=await requestBatch(Math.min(4,HEART_QUIZ_TOTAL-out.length),batch,false);misses=added?0:misses+1;if(misses>=4&&out.length===0)break;}let singleMisses=0,single=0,singleLimit=Math.max(8,Math.min(40,(HEART_QUIZ_TOTAL-out.length)*2+4));while(out.length<HEART_QUIZ_TOTAL&&single<singleLimit&&singleMisses<6){single++;const added=await requestBatch(1,batch+single,true);singleMisses=added?0:singleMisses+1;}if(out.length!==HEART_QUIZ_TOTAL){const detail=heartQuizDiagText(diag),last=diag.lastError?'；最后错误：'+diag.lastError:'';throw new Error('只收齐'+out.length+'/30题（共请求'+diag.requests+'次'+(detail?'；'+detail:'')+last+'）');}return out.slice(0,HEART_QUIZ_TOTAL).map((x,i)=>Object.assign({},x,{id:'hq'+(i+1)}));}
function heartQuizRoleIntensity(g){const rows=(g&&g.questions||[]).map(x=>Math.max(1,Math.min(5,+x.intensity||3))),level=rows.length?Math.max(1,Math.min(5,Math.round(rows.reduce((a,b)=>a+b,0)/rows.length))):3;return{level,label:HEART_QUIZ_INTENSITY[g&&g.mode==='dark'?'dark':'white'][level-1]};}
function heartQuizOpenSetup(cid){const c=getC(cid);if(!c)return;const saved=heartQuizStored();_hqResumeCandidate=saved&&saved.cid===cid?heartQuizClone(saved):null;_hq={cid,phase:'setup',mode:saved&&saved.cid===cid?saved.mode||'white':'white',level:saved&&saved.cid===cid?saved.level||2:2,source:'role',scare:saved&&saved.scare!==false};closeModal();go('heartquiz');}
function heartQuizResume(){const d=_hqResumeCandidate||heartQuizStored();if(!d)return toast('没有可以继续的问卷');_hq=heartQuizClone(d);_hq.busy=false;_hqResumeCandidate=null;if(cur().p!=='heartquiz')go('heartquiz');else render();}
function heartQuizSetMode(mode){if(!_hq||_hq.phase!=='setup')return;_hq.mode=mode==='dark'?'dark':'white';if(_hq.mode==='white')_hq.scare=false;else if(_hq.scare==null)_hq.scare=true;render();}
function heartQuizSetLevel(level){if(!_hq||_hq.phase!=='setup')return;_hq.level=Math.max(1,Math.min(3,+level||1));render();}
function heartQuizSetSource(source){if(!_hq||_hq.phase!=='setup')return;_hq.source=source==='preview'?'preview':'role';render();}
function heartQuizToggleScare(){if(!_hq||_hq.phase!=='setup'||_hq.mode!=='dark')return;_hq.scare=!_hq.scare;render();}
async function heartQuizBegin(){if(!_hq||_hq.phase!=='setup'||_hq.busy)return;const g=_hq,c=getC(g.cid);if(!c)return;g.phase='loading';g.busy=true;g.loadingDone=0;render();let questions=[],fallback=false,failure='';try{questions=await heartQuizGenerate(c,g);}catch(e){fallback=true;failure=String(e&&e.message||'角色出题失败').slice(0,150);questions=heartQuizFallback(g.mode,g.level,g.cid,Date.now());}if(_hq!==g)return;g.questions=questions;g.roleIntensity=heartQuizRoleIntensity(g);g.index=0;g.answers=[];g.reveal=false;g.phase='play';g.busy=false;delete g.loadingDone;g.generatedBy=fallback||g.source==='preview'?'preview':'role';g.startedAt=Date.now();heartQuizSave();render();if(fallback)toast(failure+'，已切换预览题库');}
function heartQuizCurrent(){return _hq&&Array.isArray(_hq.questions)?_hq.questions[_hq.index]:null;}
function heartQuizChoose(choice){const g=_hq,q=heartQuizCurrent();if(!g||g.phase!=='play'||g.reveal||!q)return;choice=Math.max(0,Math.min(q.options.length-1,+choice||0));const a={question:q.q,userChoice:choice,roleChoice:q.roleChoice,userText:q.options[choice],roleText:q.options[q.roleChoice],trait:q.traits[choice],reaction:Array.isArray(q.reactions)?String(q.reactions[choice]||''):''};g.answers[g.index]=a;g.reveal=true;const mismatch=choice!==q.roleChoice,match=!mismatch;if(mismatch&&g.mode==='dark'&&g.scare){g.scarePulse=true;try{if(navigator.vibrate)navigator.vibrate([65,45,110]);}catch(_){}}if(match&&g.mode==='white'){g.lovePulse=true;try{if(navigator.vibrate)navigator.vibrate([28,45,42]);}catch(_){}}heartQuizSave();render();if(g.scarePulse)setTimeout(()=>{if(_hq===g){g.scarePulse=false;const el=document.querySelector('.hq-shell');if(el)el.classList.remove('hq-scare');}},920);if(g.lovePulse)setTimeout(()=>{if(_hq===g){g.lovePulse=false;const el=document.querySelector('.hq-shell');if(el)el.classList.remove('hq-love');}},1120);}
function heartQuizNext(){if(!_hq||_hq.phase!=='play'||!_hq.reveal)return;if(_hq.index+1>=HEART_QUIZ_TOTAL)return heartQuizFinish();_hq.index++;_hq.reveal=false;heartQuizSave();render();}
function heartQuizCounts(g){const out={bond:0,balance:0,space:0,possess:0,obsess:0,defy:0,match:0};(g.answers||[]).forEach(a=>{if(a&&out[a.trait]!=null)out[a.trait]++;if(a&&a.userChoice===a.roleChoice)out.match++;});return out;}
function heartQuizPct(v,total){return Math.max(0,Math.min(100,Math.round((+v||0)*100/Math.max(1,total||HEART_QUIZ_TOTAL))));}
function heartQuizResult(g){const c=heartQuizCounts(g),dark=g.mode==='dark',match=c.match;if(!dark){let key='温柔同盟',desc='你们不必每题相同，却愿意把分歧说成可以靠近彼此的语言。';if(match>=25){key='心有灵犀';desc='很多选择几乎同时落下，你们已经熟悉彼此心里最细小的偏向。';}else if(c.bond>=14){key='黏人共犯';desc='你们都愿意把偏爱写得明显，日常里藏不住想靠近对方的本能。';}else if(c.space>=14){key='清醒相爱';desc='亲密没有吞掉自我，给彼此空间反而让这段关系更稳。';}else if(match<12){key='相爱不同频';desc='答案分岔得很漂亮，这不是失败，而是一张值得慢慢聊完的地图。';}return{title:key,desc,counts:c,metrics:[['默契',heartQuizPct(match,30)],['靠近',heartQuizPct(c.bond*1.25+c.balance*.45,30)],['信任',heartQuizPct(c.balance+c.space*.55,30)],['直球',heartQuizPct(c.bond,30)],['空间',heartQuizPct(c.space,30)]]};}
  let key='赤色共犯',desc='这不是一份温和的答案：你们把占有、挑衅和沉迷都推到了彼此面前。';if(match>=25&&c.possess+c.obsess>=20){key='双向沉沦';desc='你们几乎在同一处失控，也都想成为对方唯一逃不掉的方向。';}else if(c.defy>=14){key='驯服反噬';desc='你越反抗，TA越想收紧；每一次偏离都让这场审判更像一场追猎。';}else if(c.possess>=14){key='占有烙印';desc='你的答案把归属感写得太明显，TA不会只满足于一句口头保证。';}else if(match<12){key='撕咬拉扯';desc='你们的偏执没有对齐，却恰好把彼此逼到了更想征服的位置。';}return{title:key,desc,counts:c,metrics:[['默契',heartQuizPct(match,30)],['占有',heartQuizPct(c.possess,30)],['沉沦',heartQuizPct(c.obsess,30)],['反抗',heartQuizPct(c.defy,30)],['危险',heartQuizPct(c.possess+c.obsess,30)]]};}
function heartQuizFallbackLine(g,result,c){const name=(c&&(c.remark||c.name))||'TA',map={心有灵犀:'你不用每次都解释，我还是会认出你心里朝向我的那一边。',黏人共犯:'既然你也这么想，那以后别怪我总想把你留在身边。',清醒相爱:'你可以一直做你自己，我会用靠近而不是束缚来爱你。',相爱不同频:'答案不一样没关系，我想听你把每一个为什么都说给我。',温柔同盟:'我们不必猜中全部，只要每一次都愿意继续了解彼此。',双向沉沦:'原来你也想沉下去，那就别再假装自己还能轻易离开我。',驯服反噬:'你每一次反抗都被我记住了，下一次我会亲自一笔一笔讨回来。',占有烙印:'你亲手选出的归属，我不会只听一次，也不会只要一半。',撕咬拉扯:'你越不按我的期待回答，我就越想知道怎样才能让你只选我。',赤色共犯:'这三十个答案我会全部记住，以后慢慢让你兑现。'};return{name,text:map[result.title]||'这份答案我会记得，因为每一个选择里都有真实的你。'};}
async function heartQuizGenerateRoleLine(g,result,c){if(g.generatedBy!=='role')return;const diffs=(g.answers||[]).filter(a=>a.userChoice!==a.roleChoice).slice(-6).map(a=>'题目：'+a.question+'；'+S.me.name+'选：'+a.userText+'；你期待ta选：'+a.roleText).join('\n')||S.me.name+'的回答大多符合你的期待';try{let text=await chatAPI([{role:'system',content:buildSystem(c,{worldbookScope:'games'})+'\n你刚向'+S.me.name+'完成一份情侣问卷，结局是「'+result.title+'」。请以你本人身份留给ta一句话，必须结合你们的关系，以及ta的回答与你提前锁定的期待答案之间的差异，10到42个中文字，自然、具体、有情绪；不要标题、引号、标签、动作描写、解释或系统口吻。'},{role:'user',content:'结局说明：'+result.desc+'\n最近差异：\n'+diffs+'\n只说最后一句话。'}],{aux:true,max:120,temp:.72,timeout:60000,complete:true,roleInterceptAudit:null,roleInterceptStage:'心动审判结语'});text=String(cleanReply(text)||'').replace(/\[[^\]]*\]/g,'').replace(/[“”"]/g,'').replace(/\s+/g,' ').trim().slice(0,90);if(text&&_hq===g&&g.phase==='result'){g.roleLine=text;heartQuizSave();render();}}catch(_){} }
function heartQuizFinish(){const g=_hq,c=g&&getC(g.cid);if(!g||!c)return;g.phase='result';g.finishedAt=Date.now();g.result=heartQuizResult(g);g.roleLine=heartQuizFallbackLine(g,g.result,c).text;g.reveal=false;heartQuizSave();const rows=(g.answers||[]).map((a,i)=>({who:'me',text:'第'+(i+1)+'题「'+a.question+'」我选“'+a.userText+'”，'+(c.remark||c.name)+'期待我选“'+a.roleText+'”'+(a.reaction?'，并回应：“'+a.reaction+'”':'' )}));rows.push({who:'ta',text:'问卷结局：'+g.result.title+'。'+g.roleLine});gameSetHandoff(g.cid,'心动审判',rows);render();heartQuizGenerateRoleLine(g,g.result,c);}
function heartQuizExit(){if(_hq)heartQuizSave();_hq=null;_hqResumeCandidate=null;stack=[{p:'home'},{p:'gameshub'}];render();}
function heartQuizAgain(){if(!_hq)return;const cid=_hq.cid,mode=_hq.mode,level=_hq.level,source=_hq.source,scare=_hq.scare;_hqResumeCandidate=null;_hq={cid,phase:'setup',mode,level,source,scare};render();}
function heartQuizErase(){heartQuizDrop();_hq=null;_hqResumeCandidate=null;stack=[{p:'home'},{p:'gameshub'}];render();toast('这份问卷已结束');}
function heartQuizSetupHTML(g,c){const levels=HEART_QUIZ_LEVELS[g.mode],role=g.source==='role';return `<div class="hq-shell hq-setup ${g.mode==='dark'?'dark':'white'}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 大厅</button><b>心动审判</b><button onclick="heartQuizExit()">退出</button></div><div class="hq-scroll"><section class="hq-hero"><div class="hq-kicker"><i></i>COUPLE VERDICT · 30</div><h1>${heartQuizModeName(g.mode)}</h1><p>${g.mode==='dark'?'让TA把真实的妒意、占有和偏执写成一场逐步失控的审判。':'三十次选择，看看你的回答会在多少个瞬间符合TA的期待。'}</p></section><div class="hq-partner">${av(c.avatar,'lg')}<span><b>${esc(c.remark||c.name)} 向你提问</b><small>TA期待的答案和每种回答后的反应都会提前锁定</small></span></div><section class="hq-section"><label><span>选择卷面</span><span>两套独立结局</span></label><div class="hq-mode-grid"><button class="hq-choice ${g.mode==='white'?'on':''}" onclick="heartQuizSetMode('white')"><b>白卷</b><small>甜蜜、默契与真实分歧</small></button><button class="hq-choice ${g.mode==='dark'?'on':''}" onclick="heartQuizSetMode('dark')"><b>黑卷</b><small>偏执、占有与病态浪漫</small></button></div></section><section class="hq-section"><label><span>出题方式</span><span>默认由TA原创</span></label><div class="hq-source-grid"><button class="hq-choice ${role?'on':''}" onclick="heartQuizSetSource('role')"><b>TA每局新出题</b><small>结合人设、记忆和关系生成</small></button><button class="hq-choice ${!role?'on':''}" onclick="heartQuizSetSource('preview')"><b>预览题库</b><small>无需API，直接体验流程</small></button></div></section><section class="hq-section"><label><span>题目强度</span><span>${role?'由TA决定':'预览固定档'}</span></label>${role?`<div class="hq-role-level"><b>交给 ${esc(c.remark||c.name)} 定档</b><small>TA会依照自己的人设决定每题1到5级强度、整卷节奏与逐题反应。</small></div>`:`<div class="hq-level-grid">${levels.map((x,i)=>`<button class="hq-choice ${g.level===i+1?'on':''}" onclick="heartQuizSetLevel(${i+1})"><b>${esc(x[0])}</b><small>${esc(x[1])}</small></button>`).join('')}</div>`}</section>${g.mode==='dark'?`<section class="hq-section"><button class="hq-toggle ${g.scare?'on':''}" onclick="heartQuizToggleScare()"><span>答案偏差惊吓反馈</span><i></i></button><p class="hq-note">你的答案与TA期待不一致时会出现短暂红闪、裂痕和震动。系统开启“减少动态效果”时会自动减弱。</p></section>`:''}<button class="hq-primary" onclick="heartQuizBegin()">封存期待 · 开始30题</button>${_hqResumeCandidate?`<button class="hq-resume" onclick="heartQuizResume()">继续上次 · 已答 ${(_hqResumeCandidate.answers||[]).length}/30</button>`:''}</div></div>`;}
function heartQuizLoadingHTML(g,c){return `<div class="hq-shell ${g.mode==='dark'?'dark':''}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 大厅</button><b>心动审判</b><button></button></div><div class="hq-loading"><div class="hq-seal">${gameLineIcon('heartquiz')}</div><b>${g.source==='role'?esc(c.remark||c.name)+' 正在分批准备审判':'正在装订预览问卷'}</b><span>共30题${g.source==='role'?' · 已完成 '+Math.max(0,Math.min(30,+g.loadingDone||0))+'/30':''}<br>${g.source==='role'?'每一小批都由TA决定题目、强度、期待和三种反应':'你回答后才会揭晓预览期待'}</span></div></div>`;}
function heartQuizPlayHTML(g,c){const q=heartQuizCurrent(),answer=g.answers[g.index],letters=['A','B','C','D'],stage=HEART_QUIZ_STAGE[Math.min(5,Math.floor(g.index/5))],paper=g.roleIntensity||heartQuizRoleIntensity(g),level=Math.max(1,Math.min(5,Number(q&&q.intensity)||3)),levelName=HEART_QUIZ_INTENSITY[g.mode==='dark'?'dark':'white'][level-1];if(!q)return heartQuizLoadingHTML(g,c);return `<div class="hq-shell ${g.mode==='dark'?'dark':''} ${g.scarePulse?'hq-scare':''} ${g.lovePulse?'hq-love':''}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 保存退出</button><b>心动审判</b><button onclick="heartQuizExit()">退出</button></div><div class="hq-topline"><div class="hq-progress-copy"><span>${esc(stage)} · TA定档 ${esc(paper.label)}</span><span>${g.index+1} / 30</span></div><div class="hq-progress"><i style="width:${Math.round((g.index+1)*100/30)}%"></i></div></div><div class="hq-scroll"><section class="hq-question"><small>${esc(c.remark||c.name)} 已锁定期待 · 强度 ${level}/5 ${esc(levelName)}</small><h2>${esc(q.q)}</h2></section><div class="hq-options">${q.options.map((opt,i)=>{const mine=answer&&answer.userChoice===i,role=answer&&answer.roleChoice===i,both=mine&&role;return `<button class="hq-option ${mine?'mine':''} ${role?'role':''} ${both?'both':''}" ${g.reveal?'disabled':''} onclick="heartQuizChoose(${i})"><i>${letters[i]}</i><span>${esc(opt)}</span><em class="mine">你</em><em class="role">TA期待</em></button>`;}).join('')}</div>${g.reveal?`<div class="hq-reveal"><small>TA希望你这样回答</small><div><b>${esc(c.remark||c.name)}</b><p>${esc(answer.roleText)}</p><span class="hq-match ${answer.userChoice===answer.roleChoice?'':'no'}">${answer.userChoice===answer.roleChoice?'符合期待':'与期待不同'}</span></div>${answer.reaction?`<div class="hq-reaction"><b>TA反应</b><p>${esc(answer.reaction)}</p><span></span></div>`:''}</div><button class="hq-next" onclick="heartQuizNext()">${g.index+1>=30?'查看最终结果':'下一题'}</button>`:'<p class="hq-note">选定后立即揭晓TA锁定的期待，以及TA针对这个答案写下的反应。</p>'}</div><div class="hq-horror"><div><b>答案偏离</b><small>与TA锁定的期待不一致</small></div></div><div class="hq-love-fx"><i style="--x:18%;--s:18px;--d:0s">♥</i><i style="--x:37%;--s:12px;--d:.08s">♥</i><i style="--x:58%;--s:21px;--d:.03s">♥</i><i style="--x:76%;--s:14px;--d:.13s">♥</i><i style="--x:48%;--s:10px;--d:.19s">♥</i></div></div>`;}
function heartQuizResultHTML(g,c){const r=g.result||heartQuizResult(g);return `<div class="hq-shell ${g.mode==='dark'?'dark':''}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 大厅</button><b>最终结果</b><button onclick="heartQuizErase()">结束</button></div><div class="hq-scroll"><section class="hq-result-hero"><div class="hq-result-mark">${gameLineIcon('heartquiz')}</div><small>30题 · 你的回答与TA期待已揭晓</small><h1>${esc(r.title)}</h1><p>${esc(r.desc)}</p></section><section class="hq-metrics">${r.metrics.map(m=>`<div class="hq-metric"><div><span>${esc(m[0])}</span><b>${m[1]}%</b></div><i><em style="width:${m[1]}%"></em></i></div>`).join('')}</section><section class="hq-last-word"><small>TA 留给你的一句话</small><div>${av(c.avatar,'sm')}<p>${esc(g.roleLine||heartQuizFallbackLine(g,r,c).text)}</p></div></section><div class="hq-result-actions"><button onclick="heartQuizExit()">返回大厅</button><button onclick="heartQuizAgain()">换一份再测</button></div></div></div>`;}
function renderHeartQuiz(){if(!_hq){const d=heartQuizStored();if(d)_hq=heartQuizClone(d);}if(!_hq)return `<div class="hq-shell"><div class="hq-nav"><button onclick="openGames()">‹ 大厅</button><b>心动审判</b><button></button></div><div class="hq-loading"><b>没有未完成的问卷</b><span>返回游戏大厅重新选择搭档</span></div></div>`;const c=getC(_hq.cid);if(!c)return `<div class="hq-shell"><div class="hq-loading"><b>搭档已经不在通讯录</b><span>请返回游戏大厅重新选择</span></div></div>`;if(_hq.phase==='setup')return heartQuizSetupHTML(_hq,c);if(_hq.phase==='loading')return heartQuizLoadingHTML(_hq,c);if(_hq.phase==='result')return heartQuizResultHTML(_hq,c);return heartQuizPlayHTML(_hq,c);}

// Browser-only review entrance. It never runs in normal web/private sessions.
if(typeof window!=='undefined'&&typeof NORTH_PREVIEW_PARAMS==='string'&&NORTH_PREVIEW_PARAMS.includes('heartquiz')){
  window.addEventListener('load',()=>setTimeout(()=>{
    const c=getC('preview_1')||((S.contacts||[])[0]);
    if(!c)return;
    if(NORTH_PREVIEW_PARAMS.includes('heartquiz-invite')){
      const incoming=NORTH_PREVIEW_PARAMS.includes('received');
      S.messages[c.id]=[{role:incoming?'assistant':'user',type:'gameinvite',game:'heartquiz',gname:'心动审判',ge:'',status:'pending',from:incoming?'ta':undefined,id:'preview_hq_invite',time:Date.now()}];
      stack=[{p:'home'},{p:'chat',id:c.id}];
      render();
      return;
    }
    heartQuizOpenSetup(c.id);
    _hq.mode=NORTH_PREVIEW_PARAMS.includes('dark')?'dark':'white';
    _hq.level=3;
    _hq.source='preview';
    _hq.scare=true;
    render();
  },120),{once:true});
}
